import type { ReactElement } from "react";

const stepsBefore = ["모델 등록", "Adapter Operation", "Interface Operation", "Telegram Handler"];
const linkageSteps = ["어댑터", "인터페이스 정책", "서비스 정책", "커넥터"];
const stepsAfter = ["매핑", "온라인 헤더 매핑 정책", "서비스", "인터페이스"];

function Arrow(): ReactElement {
  return (
    <span className="wizard-process-next" aria-hidden="true">
      →
    </span>
  );
}

function Step({ number, label, hasNext = true }: { number: number; label: string; hasNext?: boolean }): ReactElement {
  return (
    <li className="wizard-process-item">
      <span className="wizard-process-step">
        <span className="wizard-process-number">{number}</span>
        {label}
      </span>
      {hasNext && <Arrow />}
    </li>
  );
}

// 거래 등록 순서는 같고, 연계 정보 4개를 등록하는 구간만 위자드로 묶인다.
function ProcessRow({ label, groupLabel, accent = false }: { label: string; groupLabel: string; accent?: boolean }): ReactElement {
  const linkageStart = stepsBefore.length + 1;
  const afterStart = linkageStart + linkageSteps.length;

  return (
    <div className="wizard-process-row">
      <p className="wizard-process-label">{label}</p>
      <ol className="wizard-process-steps">
        {stepsBefore.map((step, index) => (
          <Step number={index + 1} label={step} key={step} />
        ))}
        <li className="wizard-process-item">
          <div className={accent ? "wizard-process-group accent" : "wizard-process-group"}>
            <strong>{groupLabel}</strong>
            <ol className="wizard-process-steps">
              {linkageSteps.map((step, index) => (
                <Step number={linkageStart + index} label={step} hasNext={index < linkageSteps.length - 1} key={step} />
              ))}
            </ol>
          </div>
          <Arrow />
        </li>
        {stepsAfter.map((step, index) => (
          <Step number={afterStart + index} label={step} hasNext={index < stepsAfter.length - 1} key={step} />
        ))}
      </ol>
    </div>
  );
}

export function AdapterWizardProcessDiagram(): ReactElement {
  return (
    <figure className="wizard-process-diagram" aria-label="거래 등록 프로세스에서 어댑터 위자드가 통합한 구간">
      <ProcessRow label="기존 프로세스" groupLabel="화면 4개를 각각 열어 등록" />
      <p className="wizard-process-arrow" aria-hidden="true">▼</p>
      <ProcessRow label="개선 프로세스" groupLabel="어댑터 위자드 하나에서 등록" accent />
    </figure>
  );
}
