import type { ReactElement } from "react";
import igateFramework from "../../../assets/img/igate-framework.png";

type Editor = {
  name: string;
  role: string;
};

// 구조만 보여준다. 화면별 구현 내용은 업무 행에 있으므로 여기서는 반복하지 않는다.
const interfaceEditor: Editor = { name: "Interface 등록", role: "Front 시스템 쪽 요청·응답 메시지 모델 정의" };
const mappingEditor: Editor = { name: "Mapping 편집기", role: "Interface ↔ Service 필드 변환" };
const serviceEditor: Editor = { name: "Service 등록", role: "Back-End 시스템 쪽 요청·응답 메시지 모델 정의" };
const recordEditor: Editor = { name: "Record 편집기", role: "Interface·Service가 함께 쓰는 요청·응답 데이터 모델" };

function MedBox({ editor, accent = false }: { editor: Editor; accent?: boolean }): ReactElement {
  return (
    <div className={accent ? "med-box med-box-accent" : "med-box"}>
      <h4>{editor.name}</h4>
      <p>{editor.role}</p>
    </div>
  );
}

export function MessageEngineDiagram(): ReactElement {
  return (
    <figure className="message-engine-diagram" aria-label="거래 관리 도구(Message Engine)의 구조와 화면 구성">
      <img
        className="med-architecture"
        src={igateFramework}
        alt="iGate 프레임워크 구조: Front 시스템과 Back-End 시스템 사이에 Connectivity Engine(Connector), Message Engine(Converter, Interface, Mapping-Rule, Service), Process Rule Engine(Activity, Operation)이 위치"
        loading="lazy"
      />

      <div className="med-editors">
        <div className="med-flow-row">
          <MedBox editor={interfaceEditor} />
          <span className="med-flow-arrow" aria-hidden="true">↔</span>
          <MedBox editor={mappingEditor} accent />
          <span className="med-flow-arrow" aria-hidden="true">↔</span>
          <MedBox editor={serviceEditor} />
        </div>
        <p className="med-merge" aria-hidden="true">▲ 요청·응답 데이터 모델로 참조</p>
        <MedBox editor={recordEditor} />
      </div>

      <figcaption>
        거래 관리 도구가 다루는 영역은 iGate 프레임워크의 <strong>Message Engine</strong>. Connector·Converter와 Process
        Rule Engine은 범위 밖.
      </figcaption>
    </figure>
  );
}
