import type { ReactElement, ReactNode } from "react";

export function PreviewFrame({
  title,
  children,
  controls,
}: {
  title?: string;
  children: ReactNode;
  controls?: ReactNode;
}): ReactElement {
  return (
    <article className="preview-frame">
      {(title || controls) && (
        <header>
          {title && <h3>{title}</h3>}
          {controls && <div className="preview-frame-controls">{controls}</div>}
        </header>
      )}
      <div className="preview-stage">{children}</div>
    </article>
  );
}
