import type { ReactElement, ReactNode } from "react";
import { ExternalLink } from "lucide-react";
import { Badge } from "../../components/ui/badge";
import { Card } from "../../components/ui/card";
import type { DetailImage, StageVisuals } from "../projectDetailContent";
import { emphasize } from "../emphasize";
import type { ProjectSubDetail } from "../types";

function Row({ label, children }: { label: string; children: ReactNode }): ReactElement {
  return (
    <div className="grid gap-2 border-t border-border py-5 md:grid-cols-[120px_minmax(0,1fr)] md:gap-6">
      <strong className="text-body-md font-semibold">{label}</strong>
      <div className="min-w-0 text-ink-secondary [&_b]:font-semibold [&_b]:text-foreground">{children}</div>
    </div>
  );
}

// 모달 본문: 결과(수치 + 요약)를 먼저 보여주고, 역할 → 배경 → 업무 행, 마지막에 화면·데모를 둔다.
// 세부 항목 제목은 모달 탭에 이미 있으므로 본문에서는 반복하지 않는다.
export function SubDetailBlock({
  subDetail,
  visuals,
  demo,
  images,
  mediaLabel = "화면",
  mediaBadge,
}: {
  subDetail: ProjectSubDetail;
  visuals?: StageVisuals;
  demo?: ReactNode;
  images?: DetailImage[];
  mediaLabel?: string;
  mediaBadge?: string;
}): ReactElement {
  const [resultLead, ...resultDetails] = subDetail.result.split("\n");

  return (
    <section aria-label={`${subDetail.number} ${subDetail.title}`}>
      <Card className="bg-background p-5">
        <p className="text-eyebrow text-muted">결과</p>
        {subDetail.highlights.length > 0 && (
          <dl className="mt-3 grid gap-3 md:grid-flow-col md:auto-cols-fr">
            {subDetail.highlights.map((highlight) => (
              <Card className="flex flex-col-reverse justify-end gap-1 p-4" key={highlight.label}>
                <dt className="break-keep text-caption text-muted">{highlight.label}</dt>
                <dd className="break-keep text-heading-3">{highlight.value}</dd>
              </Card>
            ))}
          </dl>
        )}
        <p className="mt-4 break-keep text-title">{resultLead}</p>
        {resultDetails.length > 0 && (
          <ul className="mt-2 list-disc space-y-1 pl-5 text-body-md text-ink-secondary [&_b]:font-semibold [&_b]:text-foreground">
            {resultDetails.map((detail) => (
              <li className="break-keep" key={detail}>
                {emphasize(detail)}
              </li>
            ))}
          </ul>
        )}
      </Card>

      <div className="mt-6 border-b border-border">
        <Row label="역할">
          <p className="break-keep">{emphasize(subDetail.role)}</p>
        </Row>

        <Row label="배경">
          <p className="whitespace-pre-line break-keep">{emphasize(subDetail.background)}</p>
          {subDetail.backgroundIssues && (
            <ul className="mt-2 list-disc space-y-1 pl-5">
              {subDetail.backgroundIssues.map((issue) => (
                <li className="break-keep" key={issue}>
                  {emphasize(issue)}
                </li>
              ))}
            </ul>
          )}
          {visuals?.background && <div className="sub-detail-visual mt-4">{visuals.background}</div>}
        </Row>

        <Row label="업무">
          <div className="space-y-5">
            {subDetail.tasks.map((group) => {
              const visual = visuals?.tasks?.[group.title];
              return (
                <div key={group.title}>
                  {subDetail.tasks.length > 1 && <h4 className="mb-2 text-body-md font-semibold text-foreground">{group.title}</h4>}
                  <ul className="list-disc space-y-1 pl-5">
                    {group.items.map((item) => (
                      <li className="break-keep" key={item}>
                        {emphasize(item)}
                      </li>
                    ))}
                  </ul>
                  {visual && <div className="sub-detail-visual mt-4">{visual}</div>}
                </div>
              );
            })}
            {subDetail.blogLinks && subDetail.blogLinks.length > 0 && (
              <p className="flex flex-wrap items-center gap-x-4 gap-y-1 text-caption">
                <span className="text-muted">관련 글</span>
                {subDetail.blogLinks.map((link) => (
                  <a
                    key={link.href}
                    className="inline-flex items-center gap-1 text-accent underline underline-offset-2"
                    href={link.href}
                    target="_blank"
                    rel="noreferrer"
                  >
                    {link.label} <ExternalLink size={13} aria-hidden="true" />
                  </a>
                ))}
              </p>
            )}
          </div>
        </Row>
      </div>

      {(Boolean(images?.length) || Boolean(demo)) && (
        <div className="mt-6 grid min-w-0 gap-4">
          <p className="flex items-center gap-2 text-body-md font-semibold">
            {mediaLabel}
            {mediaBadge && <Badge variant="primary">{mediaBadge}</Badge>}
          </p>
          {images?.map((image) => (
            <figure className="m-0" key={image.src}>
              <img className="block w-full rounded-lg border border-border" src={image.src} alt={image.alt} loading="lazy" />
              {image.caption && <figcaption className="mt-2 break-keep text-caption text-muted">{image.caption}</figcaption>}
            </figure>
          ))}
          {demo && <div className="library-detail-demo">{demo}</div>}
        </div>
      )}
    </section>
  );
}
