import { useEffect, useRef, useState, type ReactElement } from "react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import { Button } from "../../components/ui/button";
import { Dialog, DialogContent, DialogTitle } from "../../components/ui/dialog";
import { portfolioData } from "../data";
import {
  demoBySubDetailId,
  imagesBySubDetailId,
  mediaBadgeBySubDetailId,
  mediaLabelBySubDetailId,
  stageVisualsBySubDetailId,
} from "../projectDetailContent";
import { SubDetailBlock } from "./SubDetailBlock";

const entries = portfolioData.projectGroups.flatMap((group) =>
  group.subDetails.map((subDetail) => ({ groupTitle: group.title, subDetail })),
);

// 목록의 2열 카드는 그대로 두고 상세만 띄운다. 이전·다음으로 프로젝트를 넘어 이어 읽을 수 있다.
export function ProjectDetailModal({
  subDetailId,
  onSelect,
  onClose,
}: {
  subDetailId: string;
  onSelect: (subDetailId: string) => void;
  onClose: () => void;
}): ReactElement | null {
  const bodyRef = useRef<HTMLDivElement | null>(null);
  const [container] = useState(() => document.querySelector<HTMLElement>(".portfolio"));

  useEffect(() => {
    bodyRef.current?.scrollTo({ top: 0 });
  }, [subDetailId]);

  const index = entries.findIndex((entry) => entry.subDetail.id === subDetailId);
  if (index < 0) return null;

  const { groupTitle, subDetail } = entries[index];
  const previous = entries[index - 1]?.subDetail;
  const next = entries[index + 1]?.subDetail;

  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        container={container}
        aria-describedby={undefined}
        className="h-[calc(100dvh-32px)] w-[calc(100vw-32px)] max-w-[1120px] overflow-hidden"
      >
        <header className="border-b border-border px-4 py-4 pr-16 sm:px-7">
          <p className="text-body-sm font-medium text-muted">{groupTitle}</p>
          <DialogTitle className="mt-0.5 break-keep text-heading-3">
            <span className="mr-2 text-subtle">{subDetail.number}</span>
            {subDetail.title}
          </DialogTitle>
        </header>

        <div ref={bodyRef} className="min-h-0 flex-1 overflow-y-auto px-4 py-6 sm:px-7">
          <SubDetailBlock
            subDetail={subDetail}
            visuals={stageVisualsBySubDetailId[subDetail.id]}
            demo={demoBySubDetailId[subDetail.id]}
            images={imagesBySubDetailId[subDetail.id]}
            mediaLabel={mediaLabelBySubDetailId[subDetail.id]}
            mediaBadge={mediaBadgeBySubDetailId[subDetail.id]}
          />
        </div>

        <footer className="flex justify-between gap-3 border-t border-border px-4 py-3 sm:px-7">
          <Button variant="utility" size="sm" className="min-w-0" disabled={!previous} onClick={() => previous && onSelect(previous.id)}>
            <ArrowLeft size={16} aria-hidden="true" />
            <span className="sm:hidden">이전</span>
            <span className="hidden truncate sm:inline">{previous ? previous.title : "이전"}</span>
          </Button>
          <Button variant="utility" size="sm" className="min-w-0" disabled={!next} onClick={() => next && onSelect(next.id)}>
            <span className="sm:hidden">다음</span>
            <span className="hidden truncate sm:inline">{next ? next.title : "다음"}</span>
            <ArrowRight size={16} aria-hidden="true" />
          </Button>
        </footer>
      </DialogContent>
    </Dialog>
  );
}
